            $iniciales = collect(explode(' ', $lead->nombre ?: 'Sin nombre'))->filter()->take(2)->map(fn ($parte) => mb_substr($parte, 0, 1))->join('');
            $ultimoMensaje = $lead->ultimoMensajeWhatsapp;
            $sinResponder = $lead->etapa->tipo === 'activa' && $ultimoMensaje?->direccion === 'entrante';
            $horasSinResponder = $sinResponder ? (int) $ultimoMensaje->ocurrio_at->diffInHours(now()) : null;
            $vencido = $sinResponder && ($horasSinResponder ?? 0) >= 4;
            $resumenMensaje = $ultimoMensaje?->contenido ?: ($lead->notas ?: 'Conversación pendiente de seguimiento.');
          @endphp
          <article class="crm-lead-card {{ $sinResponder ? 'sin-responder' : '' }} {{ $vencido ? 'vencido' : '' }}" data-lead-id="{{ $lead->id }}" data-value="{{ $lead->valor_estimado }}" tabindex="0" role="button" aria-label="Abrir conversación con {{ $lead->nombre ?: 'Sin nombre' }}">
            <div class="crm-card-head"><span class="crm-avatar">{{ strtoupper($iniciales) }}</span><strong>{{ $lead->nombre ?: 'Sin nombre' }}</strong>@if($sinResponder)<span class="crm-badge-respuesta {{ $vencido ? 'urgente' : '' }}">{{ $vencido ? '+4h' : 'Responder' }}</span>@elseif($lead->mensajes_whatsapp_count)<i class="bi bi-check2-all" title="Conversación registrada"></i>@endif</div>
