in-top:3px}.crm-guardar{width:100%;justify-content:center;margin-top:10px}.crm-cerrar-movil{display:none}.crm-chat{min-width:0;display:grid;grid-template-rows:55px 38px 1fr;background:var(--gc-fondo)}.crm-chat-head{display:flex;align-items:center;justify-content:space-between;padding:9px 14px;background:var(--gc-superficie);border-bottom:1px solid var(--gc-borde)}.crm-chat-identidad{display:flex;align-items:center;gap:9px}.crm-chat-identidad div{display:flex;flex-direction:column}.crm-chat-identidad strong{font-size:12px}.crm-chat-identidad small{font-size:9.5px;color:var(--gc-gris)}.crm-chat-tabs{display:flex;gap:3px;background:var(--gc-superficie);border-bottom:1px solid var(--gc-borde);padding-left:12px}.crm-chat-tabs button{border:0;background:transparent;color:var(--gc-gris);font-size:11px;padding:8px 12px;cursor:pointer;border-bottom:2px solid transparent}.crm-chat-tabs button.activo{color:var(--gc-info);border-color:var(--gc-info);font-weight:600}.crm-chat-panel{display:none;min-height:0}.crm-chat-panel.activo{display:grid}.crm-chat-panel#panelConversacion{grid-template-rows:1fr auto 55px}.crm-mensajes{overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:8px}.crm-mensaje{max-width:70%;padding:9px 10px 6px;background:var(--gc-superficie);border:1px solid var(--gc-borde);border-radius:7px;align-self:flex-start;font-size:11px;line-height:1.45}.crm-mensaje.saliente{align-self:flex-end;background:#d9fdd3;border-color:#c6ecc0;color:#17321a}.crm-mensaje small{display:flex;justify-content:flex-end;gap:5px;margin-top:4px;font-size:8.5px;color:#6b7280}.crm-media-img,.crm-media-video{display:block;width:min(320px,100%);max-height:260px;object-fit:contain;border-radius:6px;margin-bottom:6px;background:#0f172a}.crm-media-audio{width:260px;max-width:100%;height:34px;margin-bottom:5px}.crm-archivo{display:flex;align-items:center;gap:8px;width:min(300px,100%);border:1px solid var(--gc-borde);border-radius:6px;padding:8px;color:inherit;text-decoration:none;background:rgba(255,255,255,.45);margin-bottom:6px}.crm-archivo i{font-size:18px;color:var(--gc-info)}.crm-archivo span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.crm-archivo small{margin:1px 0 0;justify-content:flex-start}.crm-respuestas-rapidas{display:flex;gap:6px;overflow-x:auto;padding:7px 12px;background:var(--gc-superficie);border-top:1px solid var(--gc-borde)}.crm-respuestas-rapidas button{border:1px solid var(--gc-borde);background:var(--gc-fondo);color:var(--gc-texto);border-radius:14px;padding:5px 9px;font-size:10px;white-space:nowrap;cursor:pointer}.crm-respuestas-rapidas button:disabled{opacity:.45;cursor:not-allowed}.crm-composer{display:grid;grid-template-columns:34px 1fr 38px;gap:7px;padding:9px 12px;background:var(--gc-superficie);border-top:1px solid var(--gc-borde)}.crm-composer input{border:0;border-radius:7px;background:var(--gc-fondo);padding:9px 12px;color:var(--gc-texto);min-width:0}.crm-composer input:disabled{color:var(--gc-gris);opacity:.75}.crm-composer button{border:0;border-radius:50%;background:var(--gc-fondo);color:var(--gc-gris-claro)}.crm-composer button:last-child{background:var(--gc-info);color:#fff;opacity:.45}.crm-composer button:last-child:not(:disabled){opacity:1;cursor:pointer}.crm-historial{padding:20px;overflow-y:auto}.crm-historial-item{display:grid;grid-template-columns:26px 1fr;gap:9px;margin-bottom:16px;font-size:11px}.crm-historial-item i{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--gc-info-suave);color:var(--gc-info)}.crm-historial-item div{display:flex;flex-direction:column;gap:2px}.crm-historial-item small{color:var(--gc-gris)}.crm-cargando{margin:auto;color:var(--gc-gris);font-size:12px}.crm-nuevo-modal{max-width:700px!important}.crm-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.crm-ancho{grid-column:1/-1}.crm-form-acciones{display:flex;gap:8px;margin-top:16px}
.crm-metricas{grid-template-columns:repeat(8,minmax(118px,1fr))}.crm-metrica:nth-child(6)>i,.crm-metrica:nth-child(7)>i{background:var(--gc-rojo-suave);color:var(--gc-rojo)}.crm-lead-card.sin-responder{background:color-mix(in srgb,var(--gc-amarillo-suave) 45%,var(--gc-superficie));border-left-color:var(--gc-amarillo)}.crm-lead-card.vencido{background:color-mix(in srgb,var(--gc-rojo-suave) 55%,var(--gc-superficie));border-left-color:var(--gc-rojo)}.crm-badge-respuesta{height:18px;display:inline-grid;place-items:center;border-radius:9px;background:var(--gc-amarillo-suave);color:var(--gc-amarillo);font-size:8px;font-weight:800;padding:0 6px;white-space:nowrap}.crm-badge-respuesta.urgente{background:var(--gc-rojo-suave);color:var(--gc-rojo)}.crm-tiempo.alerta{color:var(--gc-rojo);font-weight:800}
.crm-seguimiento-filtros{display:flex;gap:6px;overflow-x:auto;margin:-4px 0 12px;padding-bottom:2px}.crm-filtro-chip{height:30px;display:inline-flex;align-items:center;gap:6px;border:1px solid var(--gc-borde);border-radius:15px;background:var(--gc-superficie);color:var(--gc-gris);padding:0 11px;font-size:11px;font-weight:700;text-decoration:none;white-space:nowrap}.crm-filtro-chip.activo{background:var(--gc-info-suave);border-color:var(--gc-info);color:var(--gc-info)}.crm-filtro-chip.activo.alerta{background:var(--gc-amarillo-suave);border-color:var(--gc-amarillo);color:var(--gc-amarillo)}.crm-filtro-chip.activo.urgente,.crm-filtro-chip.activo.error{background:var(--gc-rojo-suave);border-color:var(--gc-rojo);color:var(--gc-rojo)}
.crm-campo-mensaje{min-width:0;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;border-radius:7px;background:var(--gc-fondo);overflow:hidden}.crm-campo-mensaje input#chatInputMensaje{border:0!important;border-radius:0!important;background:transparent!important}.crm-adjunto-pill{height:28px;max-width:190px;margin-right:4px;border-radius:14px!important;display:flex!important;align-items:center;gap:4px;padding:0 8px!important;background:var(--gc-info-suave)!important;color:var(--gc-info)!important;font-size:10px;opacity:1!important}.crm-adjunto-pill[hidden]{display:none!important}.crm-adjunto-pill span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.crm-composer>#chatAdjuntarBtn:not(:disabled){cursor:pointer;color:var(--gc-info)}.crm-composer>#chatEnviarBtn:not(:disabled){opacity:1;cursor:pointer}
.crm-estado-msg{display:inline-flex;align-items:center;gap:3px;border-radius:10px;padding:1px 6px;background:rgba(255,255,255,.48);font-weight:700}.crm-estado-msg.estado-leido{color:var(--gc-info)}.crm-estado-msg.estado-error{color:var(--gc-rojo);background:var(--gc-rojo-suave)}.crm-reintentar-msg{border:0;border-radius:10px;background:var(--gc-rojo-suave);color:var(--gc-rojo);font-size:8.5px;font-weight:800;padding:2px 7px;cursor:pointer}.crm-mensaje.error{border-color:var(--gc-rojo);background:color-mix(in srgb,var(--gc-rojo-suave) 45%,var(--gc-superficie))}.crm-mensaje.saliente.error{background:color-mix(in srgb,var(--gc-rojo-suave) 65%,#d9fdd3)}
@media(max-width:1100px){.crm-metricas{grid-template-columns:repeat(4,1fr)}.crm-board{min-height:calc(100vh - 320px)}}
@media(max-width:760px){.gc-content{padding:14px 12px}.crm-cabecera{align-items:flex-start}.crm-cabecera h2{font-size:17px}.crm-cabecera p{display:none}.crm-acciones .btn-outline{font-size:0;padding:8px}.crm-acciones .btn-outline i{font-size:14px}.crm-metricas{grid-template-columns:repeat(2,1fr)}.crm-filtros{grid-template-columns:1fr 1fr}.crm-buscador{grid-column:1/-1}.crm-filtros>.btn-icon{display:none}.crm-board{min-height:520px}.crm-columna{width:84vw;min-width:84vw}.crm-conversacion-modal{height:calc(100vh - 16px);grid-template-columns:1fr;grid-template-rows:auto 1fr}.crm-ficha{border-right:0;border-bottom:1px solid var(--gc-borde);padding:12px 14px;max-height:300px}.crm-ficha-titulo{margin-bottom:8px}.crm-ficha>label,.crm-ficha .crm-ultima,.crm-ficha textarea{display:none}.crm-ficha select,.crm-ficha .crm-input-moneda{margin-top:7px}.crm-cerrar-movil{display:inline-flex}.crm-chat-head>button{display:none}.crm-chat{grid-template-rows:52px 38px 1fr}.crm-mensaje{max-width:88%}.crm-media-img,.crm-media-video{width:100%;max-height:230px}.crm-respuestas-rapidas{padding:7px 10px}.crm-form-grid{grid-template-columns:1fr}.crm-ancho{grid-column:auto}}
</style>
@endpush

@push('scripts')
<script>
const crmCsrf=@json(csrf_token());const crmBase=@json(url('/crm/leads'));let leadActivo=null;let bloqueoClickHasta=0;let firmaMensajes=null;let archivoChat=null;
function abrirNuevoLead(){document.getElementById('modalNuevoLead').classList.add('abierto')}function cerrarNuevoLead(){document.getElementById('modalNuevoLead').classList.remove('abierto')}
function cerrarConversacion(){document.getElementById('modalConversacion').classList.remove('abierto');leadActivo=null;quitarAdjuntoChat()}
async function peticionCrm(url,opciones={}){const esForm=opciones.body instanceof FormData;const headers={'Accept':'application/json','X-CSRF-TOKEN':crmCsrf,...(opciones.headers||{})};if(!esForm)headers['Content-Type']='application/json';const respuesta=await fetch(url,{...opciones,headers});const datos=await respuesta.json();if(!respuesta.ok)throw new Error(datos.message||'No se pudo completar la acción.');return datos}
async function abrirConversacion(id){leadActivo=id;firmaMensajes=null;document.getElementById('modalConversacion').classList.add('abierto');document.getElementById('chatMensajes').innerHTML='<div class="crm-cargando">Cargando conversación...</div>';try{const datos=await peticionCrm(crmBase+'/'+id);pintarFicha(datos.lead);pintarMensajes(datos.mensajes);pintarHistorial(datos.lead)}catch(error){mostrarToast(error.message,'error');cerrarConversacion()}}
function pintarFicha(lead){document.getElementById('fichaNombre').textContent=lead.nombre;document.getElementById('chatNombre').textContent=lead.nombre;document.getElementById('fichaTelefono').textContent=lead.telefono;document.getElementById('fichaCanal').textContent=lead.canal||'Ingreso manual';document.getElementById('fichaEtapa').value=String(lead.etapa_crm_id);const vendedor=document.getElementById('fichaVendedor');if(vendedor)vendedor.value=lead.vendedor_id||'';const vendedorTexto=document.getElementById('fichaVendedorTexto');if(vendedorTexto)vendedorTexto.textContent=lead.vendedor||'Sin asignar';document.getElementById('fichaValor').value=lead.valor_estimado||0;document.getElementById('fichaNotas').value=lead.notas||'';document.getElementById('fichaUltima').textContent=lead.ultima_interaccion||'Sin interacción';document.getElementById('chatSubtitulo').textContent=(lead.canal||'Ingreso manual')+' · '+(lead.vendedor||'Sin asignar');document.getElementById('chatAvatar').textContent=iniciales(lead.nombre);configurarComposer(lead)}
function pintarMensajes(mensajes){const firma=mensajes.map(m=>[m.id,m.estado,m.archivo_url,m.contenido].join(':')).join('|');if(firma===firmaMensajes)return;firmaMensajes=firma;const contenedor=document.getElementById('chatMensajes');const estabaAbajo=contenedor.scrollTop+contenedor.clientHeight>=contenedor.scrollHeight-40;contenedor.innerHTML='';if(!mensajes.length){contenedor.innerHTML='<div class="crm-cargando">Sin mensajes registrados.</div>';return}mensajes.forEach(mensaje=>contenedor.appendChild(crearBurbujaMensaje(mensaje)));if(estabaAbajo)contenedor.scrollTop=contenedor.scrollHeight}
function crearBurbujaMensaje(mensaje){const burbuja=document.createElement('div');burbuja.className='crm-mensaje '+(mensaje.direccion==='saliente'?'saliente ':'')+(mensaje.estado==='error'?'error':'');const adjunto=crearAdjuntoMensaje(mensaje);if(adjunto)burbuja.appendChild(adjunto);if(mensaje.contenido){const texto=document.createElement('div');texto.textContent=mensaje.contenido;burbuja.appendChild(texto)}else if(!adjunto){const texto=document.createElement('div');texto.textContent='Archivo adjunto';burbuja.appendChild(texto)}const meta=document.createElement('small');const tiempo=document.createElement('span');tiempo.textContent=mensaje.fecha+' '+mensaje.hora;meta.appendChild(tiempo);if(mensaje.direccion==='saliente')meta.appendChild(crearEstadoMensaje(mensaje));if(mensaje.puede_reintentar){const retry=document.createElement('button');retry.type='button';retry.className='crm-reintentar-msg';retry.textContent='Reintentar';retry.onclick=()=>reintentarMensajeChat(mensaje.id,retry);meta.appendChild(retry)}burbuja.appendChild(meta);return burbuja}
function crearEstadoMensaje(mensaje){const estado=document.createElement('span');estado.className='crm-estado-msg estado-'+mensaje.estado;const icono=document.createElement('i');icono.className='bi '+(mensaje.estado_icono||'bi-check');const texto=document.createElement('span');texto.textContent=mensaje.estado_texto||mensaje.estado;estado.append(icono,texto);return estado}
function crearAdjuntoMensaje(mensaje){if(!mensaje.archivo_url)return null;if(mensaje.tipo==='imagen'){const imagen=document.createElement('img');imagen.className='crm-media-img';imagen.src=mensaje.archivo_url;imagen.alt=mensaje.nombre_archivo||'Imagen recibida';imagen.loading='lazy';return imagen}if(mensaje.tipo==='audio'){const audio=document.createElement('audio');audio.className='crm-media-audio';audio.src=mensaje.archivo_url;audio.controls=true;return audio}if(mensaje.tipo==='video'){const video=document.createElement('video');video.className='crm-media-video';video.src=mensaje.archivo_url;video.controls=true;return video}const enlace=document.createElement('a');enlace.className='crm-archivo';enlace.href=mensaje.archivo_url;enlace.target='_blank';enlace.rel='noopener';enlace.download=mensaje.nombre_archivo||'';const icono=document.createElement('i');icono.className='bi bi-file-earmark-arrow-down';const caja=document.createElement('div');const nombre=document.createElement('span');nombre.textContent=mensaje.nombre_archivo||'Abrir archivo';const detalle=document.createElement('small');detalle.textContent=[mensaje.mime_type,formatoBytes(mensaje.tamano_archivo)].filter(Boolean).join(' · ');caja.append(nombre,detalle);enlace.append(icono,caja);return enlace}
function configurarComposer(lead){const input=document.getElementById('chatInputMensaje');const boton=document.getElementById('chatEnviarBtn');const adjuntar=document.getElementById('chatAdjuntarBtn');input.value='';quitarAdjuntoChat();input.disabled=!lead.puede_enviar;boton.disabled=!lead.puede_enviar;adjuntar.disabled=!lead.puede_enviar;document.querySelectorAll('#respuestasRapidas button').forEach(b=>{b.disabled=!lead.puede_enviar;if(b.dataset.respuestaTipo==='cotizacion'){const valor=Number(lead.valor_estimado||0);const monto=valor>0?' por Bs '+new Intl.NumberFormat('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2}).format(valor):'';b.dataset.respuesta='Hola '+lead.nombre+', te compartimos la cotización'+monto+'. Quedamos atentos a tu confirmación.'}});input.placeholder=lead.puede_enviar?'Escribe un mensaje o adjunta una cotización...':(lead.motivo_envio||'Envío disponible al conectar Meta');input.title=input.placeholder;boton.title=lead.puede_enviar?'Enviar mensaje':input.placeholder;adjuntar.title=lead.puede_enviar?'Adjuntar PDF, imagen, audio o video':input.placeholder}
function seleccionarAdjuntoChat(){const input=document.getElementById('chatArchivoInput');if(!input.disabled)input.click()}
function pintarAdjuntoChat(){const pill=document.getElementById('chatAdjuntoPill');const nombre=pill.querySelector('span');if(!archivoChat){pill.hidden=true;nombre.textContent='';return}nombre.textContent=archivoChat.name;nombre.title=archivoChat.name+' · '+formatoBytes(archivoChat.size);pill.hidden=false}
function quitarAdjuntoChat(){archivoChat=null;const input=document.getElementById('chatArchivoInput');if(input)input.value='';const pill=document.getElementById('chatAdjuntoPill');if(pill){pill.hidden=true;pill.querySelector('span').textContent=''}}
function agregarMensajeChat(mensaje){firmaMensajes=null;const contenedor=document.getElementById('chatMensajes');if(contenedor.querySelector('.crm-cargando'))contenedor.innerHTML='';contenedor.appendChild(crearBurbujaMensaje(mensaje));contenedor.scrollTop=contenedor.scrollHeight}
async function enviarMensajeChat(){if(!leadActivo)return;const input=document.getElementById('chatInputMensaje');const boton=document.getElementById('chatEnviarBtn');const adjuntar=document.getElementById('chatAdjuntarBtn');const mensaje=input.value.trim();if(!mensaje&&!archivoChat)return;boton.disabled=true;input.disabled=true;adjuntar.disabled=true;try{let body;if(archivoChat){body=new FormData();body.append('mensaje',mensaje);body.append('archivo',archivoChat)}else{body=JSON.stringify({mensaje})}const datos=await peticionCrm(crmBase+'/'+leadActivo+'/mensajes',{method:'POST',body});input.value='';quitarAdjuntoChat();agregarMensajeChat(datos.mensaje);mostrarToast(datos.message,'exito')}catch(error){mostrarToast(error.message,'error')}finally{input.disabled=false;boton.disabled=false;adjuntar.disabled=false;input.focus()}}
async function reintentarMensajeChat(mensajeId,boton){if(!leadActivo)return;boton.disabled=true;boton.textContent='Enviando...';try{const datos=await peticionCrm(crmBase+'/'+leadActivo+'/mensajes/'+mensajeId+'/reintentar',{method:'POST',body:JSON.stringify({})});agregarMensajeChat(datos.mensaje);mostrarToast(datos.message,'exito')}catch(error){mostrarToast(error.message,'error');boton.disabled=false;boton.textContent='Reintentar'}}
async function refrescarConversacion(){if(!leadActivo||!document.getElementById('modalConversacion').classList.contains('abierto'))return;try{const datos=await peticionCrm(crmBase+'/'+leadActivo);pintarMensajes(datos.mensajes);document.getElementById('fichaUltima').textContent=datos.lead.ultima_interaccion||'Sin interacción'}catch(error){}}
function pintarHistorial(lead){document.getElementById('chatHistorial').innerHTML='<div class="crm-historial-item"><i class="bi bi-person-plus"></i><div><strong>Lead creado</strong><small>'+escapar(lead.creado||'-')+'</small></div></div><div class="crm-historial-item"><i class="bi bi-arrow-left-right"></i><div><strong>Etapa actual: '+escapar(lead.etapa)+'</strong><small>Actualizada '+escapar(lead.etapa_actualizada||'-')+'</small></div></div>'}
function cambiarTabChat(tab){document.querySelectorAll('.crm-chat-tabs button').forEach(b=>b.classList.toggle('activo',b.dataset.tab===tab));document.querySelectorAll('.crm-chat-panel').forEach(p=>p.classList.toggle('activo',p.id==='panel'+tab.charAt(0).toUpperCase()+tab.slice(1)))}
async function guardarFicha(){if(!leadActivo)return;const vendedor=document.getElementById('fichaVendedor');const payload={etapa_crm_id:document.getElementById('fichaEtapa').value,valor_estimado:document.getElementById('fichaValor').value,notas:document.getElementById('fichaNotas').value};if(vendedor)payload.vendedor_id=vendedor.value||null;try{const datos=await peticionCrm(crmBase+'/'+leadActivo+'/ficha',{method:'PATCH',body:JSON.stringify(payload)});await moverTarjetaLocal(leadActivo,payload.etapa_crm_id);const tarjeta=document.querySelector('[data-lead-id="'+leadActivo+'"]');if(tarjeta){tarjeta.dataset.value=payload.valor_estimado||0;tarjeta.querySelector('.crm-resumen-mensaje span').textContent=payload.notas||'Conversación pendiente de seguimiento.'}actualizarContadores();mostrarToast(datos.message,'exito')}catch(error){mostrarToast(error.message,'error')}}
async function moverLead(id,etapaId){try{const datos=await peticionCrm(crmBase+'/'+id+'/etapa',{method:'PATCH',body:JSON.stringify({etapa_crm_id:etapaId})});await moverTarjetaLocal(id,etapaId);document.getElementById('fichaEtapa').value=String(etapaId);actualizarContadores();mostrarToast(datos.message,'exito')}catch(error){mostrarToast(error.message,'error')}}
async function moverTarjetaLocal(id,etapaId){const tarjeta=document.querySelector('[data-lead-id="'+id+'"]');const destino=document.querySelector('[data-drop-etapa="'+etapaId+'"]');if(tarjeta&&destino)destino.insertBefore(tarjeta,destino.querySelector('.crm-columna-vacia'))}
function actualizarContadores(){document.querySelectorAll('.crm-columna').forEach(columna=>{const tarjetas=[...columna.querySelectorAll('.crm-lead-card')];columna.querySelector('.crm-conteo').textContent=tarjetas.length;const total=tarjetas.reduce((s,t)=>s+Number(t.dataset.value||0),0);columna.querySelector('.crm-columna-valor').textContent=new Intl.NumberFormat('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2}).format(total)})}
function iniciales(nombre){return nombre.split(/\s+/).filter(Boolean).slice(0,2).map(p=>p.charAt(0)).join('').toUpperCase()}function escapar(valor){const nodo=document.createElement('div');nodo.textContent=valor;return nodo.innerHTML}function formatoBytes(bytes){const n=Number(bytes||0);if(!n)return '';if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
document.querySelectorAll('.crm-lead-card').forEach(tarjeta=>{let arrastre=null;tarjeta.addEventListener('pointerdown',evento=>{if(evento.button!==0||evento.target.closest('button,a,input,select,textarea'))return;arrastre={x:evento.clientX,y:evento.clientY,activo:false,destino:null};tarjeta.setPointerCapture(evento.pointerId)});tarjeta.addEventListener('pointermove',evento=>{if(!arrastre)return;const distancia=Math.hypot(evento.clientX-arrastre.x,evento.clientY-arrastre.y);if(!arrastre.activo&&distancia>8){arrastre.activo=true;tarjeta.classList.add('arrastrando')}if(!arrastre.activo)return;evento.preventDefault();document.querySelectorAll('.crm-columna-body.destino').forEach(c=>c.classList.remove('destino'));const elemento=document.elementFromPoint(evento.clientX,evento.clientY);arrastre.destino=elemento?.closest('.crm-columna-body')||null;if(arrastre.destino)arrastre.destino.classList.add('destino');const board=document.getElementById('crmBoard');const rect=board.getBoundingClientRect();if(evento.clientX>rect.right-50)board.scrollLeft+=12;if(evento.clientX<rect.left+50)board.scrollLeft-=12});tarjeta.addEventListener('pointerup',evento=>{if(!arrastre)return;tarjeta.releasePointerCapture(evento.pointerId);tarjeta.classList.remove('arrastrando');document.querySelectorAll('.crm-columna-body.destino').forEach(c=>c.classList.remove('destino'));if(arrastre.activo){bloqueoClickHasta=Date.now()+350;if(arrastre.destino)moverLead(tarjeta.dataset.leadId,arrastre.destino.dataset.dropEtapa)}arrastre=null});tarjeta.addEventListener('pointercancel',()=>{tarjeta.classList.remove('arrastrando');arrastre=null});tarjeta.addEventListener('click',()=>{if(Date.now()>bloqueoClickHasta)abrirConversacion(tarjeta.dataset.leadId)});tarjeta.addEventListener('keydown',evento=>{if(evento.key==='Enter'||evento.key===' '){evento.preventDefault();abrirConversacion(tarjeta.dataset.leadId)}})});
document.getElementById('chatInputMensaje')?.addEventListener('keydown',evento=>{if(evento.key==='Enter'&&!evento.shiftKey){evento.preventDefault();enviarMensajeChat()}});
document.getElementById('chatArchivoInput')?.addEventListener('change',evento=>{archivoChat=evento.target.files?.[0]||null;pintarAdjuntoChat();document.getElementById('chatInputMensaje').focus()});
document.querySelectorAll('#respuestasRapidas button').forEach(boton=>boton.addEventListener('click',()=>{const input=document.getElementById('chatInputMensaje');if(input.disabled)return;input.value=boton.dataset.respuesta||'';input.focus()}));
setInterval(refrescarConversacion,5000);
function mostrarToast(mensaje,tipo){let toast=document.getElementById('toastGiseca');if(!toast){toast=document.createElement('div');toast.id='toastGiseca';document.body.appendChild(toast)}toast.textContent=mensaje;toast.className='toast-giseca mostrar '+(tipo||'');setTimeout(()=>toast.classList.remove('mostrar'),2800)}
@if(session('exito')) mostrarToast(@json(session('exito')),'exito'); @endif
</script>
@endpush
